import{_ as a,o as t,c as i,a4 as r}from"./chunks/framework.CzJ_HCFe.js";const u=JSON.parse('{"title":"Capital Deployment Source Profile","description":"","frontmatter":{},"headers":[],"relativePath":"reference/41-business-evidence-audit.md","filePath":"reference/41-business-evidence-audit.md","lastUpdated":1788519103000}'),n={name:"reference/41-business-evidence-audit.md"};function o(d,e,s,c,l,p){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="capital-deployment-source-profile" tabindex="-1">Capital Deployment Source Profile <a class="header-anchor" href="#capital-deployment-source-profile" aria-label="Permalink to &quot;Capital Deployment Source Profile&quot;">​</a></h1><h2 id="scope-and-authority" tabindex="-1">Scope and authority <a class="header-anchor" href="#scope-and-authority" aria-label="Permalink to &quot;Scope and authority&quot;">​</a></h2><p>The <code>business</code> compatibility key now means <strong>deploying capital / business investment</strong>, not founding or launching a company generally. The verified claim is <code>muhurta.capital_deployment</code>.</p><p>The source is Rama Daivajna, <em>Muhurta Chintamani</em>, undated Sanskrit text with Hindi commentary, Nakshatra-prakarana, “Dravyaprayoga and taking a loan,” verse 27, printed pages 38–39 (Internet Archive OCR lines 2578–2599).</p><p>The commentary explains Dravyaprayoga as putting funds to work, including lending or investing them in employment/business. The product already has a separate lender-side profile, so this key is restricted to deploying investment capital in an enterprise. Marketplace opening, inventory purchase and company formation remain distinct acts.</p><h2 id="exact-crosswalk" tabindex="-1">Exact crosswalk <a class="header-anchor" href="#exact-crosswalk" aria-label="Permalink to &quot;Exact crosswalk&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Source criterion</th><th>Implementation</th><th>Boundary</th></tr></thead><tbody><tr><td>Twelve named Nakshatras</td><td>Exact <code>allowed_nakshatras</code></td><td>Hard slot-time gate</td></tr><tr><td>Chara Lagna</td><td><code>required_lagna_class = &#39;Chara&#39;</code></td><td>Hard slot-time gate</td></tr><tr><td>Benefics in the 5th and 9th</td><td>Manual check</td><td>Mandatory chart review</td></tr><tr><td>Eighth house unoccupied</td><td>Manual check</td><td>Mandatory chart review</td></tr></tbody></table><p><code>manual_prerequisites = true</code> caps results below Excellent until the chart is checked. The former Amrit Choghadiya, Nanda Tithi, weekday and Sthira-Lagna proxies have been removed because verse 27 does not supply them.</p><p>Commercial viability, diversification, liquidity, contracts, taxation, securities law, due diligence and qualified advice take precedence over timing.</p>',9)])])}const m=a(n,[["render",o]]);export{u as __pageData,m as default};
